        var template=new ControlTemplate(typeof(Button)); var border=new FrameworkElementFactory(typeof(Border)); border.SetValue(Border.CornerRadiusProperty,new CornerRadius(18)); border.SetBinding(Border.BackgroundProperty,new System.Windows.Data.Binding("Background"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)}); var presenter=new FrameworkElementFactory(typeof(ContentPresenter)); presenter.SetValue(FrameworkElement.MarginProperty,new Thickness(14,10,14,10)); presenter.SetBinding(ContentPresenter.HorizontalAlignmentProperty,new System.Windows.Data.Binding("HorizontalContentAlignment"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)}); border.AppendChild(presenter); template.VisualTree=border; b.Setters.Add(new Setter(Control.TemplateProperty,template)); var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true}; hover.Setters.Add(new Setter(UIElement.OpacityProperty,0.78)); b.Triggers.Add(hover); var focus=new Trigger{Property=UIElement.IsKeyboardFocusedProperty,Value=true}; focus.Setters.Add(new Setter(Control.BackgroundProperty,Green)); b.Triggers.Add(focus); Resources.Add(typeof(Button),b);
        var t=new Style(typeof(TextBox)); t.Setters.Add(new Setter(Control.BackgroundProperty,Bg)); t.Setters.Add(new Setter(Control.ForegroundProperty,Ink)); t.Setters.Add(new Setter(Control.BorderBrushProperty,Brush("#41516A"))); t.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(10))); t.Setters.Add(new Setter(Control.FontSizeProperty,15.0)); t.Setters.Add(new Setter(TextBox.CaretBrushProperty,Ink)); Resources.Add(typeof(TextBox),t);
        var c=new Style(typeof(CheckBox)); c.Setters.Add(new Setter(Control.ForegroundProperty,Ink)); c.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(0,10,0,10))); Resources.Add(typeof(CheckBox),c);InstallSoftStyles();
